"""Attenuator manager"""
from builtins import object
from taf.ul.trs_e2e_fw.lib.attenuator.tool_factory import ToolFactory
from ute_common_store.store import Store

store = Store()


class AttenuatorManager(object):
    """Attenuator manager"""
    def __init__(self):
        pass

    def attenuator_setup(self, device, alias):
        """Attentuator setup"""
        attenuator_factory_obj = ToolFactory(device)
        tool_object = attenuator_factory_obj.get_tool_obj()
        tool_object.attenuator_setup(device)
        store.add(tool_object, alias)

    def attenuator_configure(self, operation, alias, **kwargs):
        """Attentuator configure"""
        tool_object = store.get(alias)
        tool_object.attenuator_configure(operation, **kwargs)

    def attenuator_teardown(self, alias):
        """Attentuator teardown"""
        tool_object = store.get(alias)
        tool_object.attenuator_teardown()
        store.remove(alias)
